/// Every registered function of every unit.
pub fn funcs(out: &mut Vec<(u32, crate::AbiFn)>) {
    engine_core::units::funcs(out);
    engine_gamebryo::units::funcs(out);
    engine_bs::units::funcs(out);
    engine_havok::units::funcs(out);
    engine_speedtree::units::funcs(out);
    engine_fallout_facegen::units::funcs(out);
    engine_fallout_cell::units::funcs(out);
    engine_fallout_forms::units::funcs(out);
    engine_fallout_pathfinding::units::funcs(out);
    engine_fallout_ai::units::funcs(out);
    engine_fallout_env::units::funcs(out);
    engine_fallout_interface::units::funcs(out);
    engine_fallout_magic::units::funcs(out);
    engine_fallout_misc::units::funcs(out);
    engine_fallout_script::units::funcs(out);
    engine_fallout_unplaced_a::units::funcs(out);
    engine_fallout_unplaced_b::units::funcs(out);
    engine_platform::units::funcs(out);
    engine_typed::units::funcs(out);
}

/// One engine crate's `units::funcs`.
pub type Funcs = fn(&mut Vec<(u32, crate::AbiFn)>);

